struct Ping  { int id;  };
struct Order { int qty; };
using Message = std::variant<Ping, Order>;

struct Dispatch {
  const Table& table;
  void operator()(const Ping&  p) const { table.at("ping")(p.id); }
  void operator()(const Order& o) const { table.at("order")(o.qty); }
};
void route(const Message& m, const Table& t) { std::visit(Dispatch{t}, m); }
